-- Domain 01: Platform & Workspace | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 347
CREATE FUNCTION public.app__default_from(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v text;
BEGIN
  SELECT coalesce(d.default_from, 'no-reply@' || d.domain) INTO v FROM email_sender_domains d
   WHERE d.tenant_id = p_tenant_id AND lower(d.status) IN ('verified','active')
   ORDER BY d.default_from IS NOT NULL DESC, d.created_at LIMIT 1;
  IF v IS NULL THEN RAISE EXCEPTION 'Verify a sending domain (Settings > Email) before sending email'; END IF;
  RETURN v;
END $$;

-- @seq 348
CREATE FUNCTION public.app__insert_json(p_table text, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_cols text; v uuid;
BEGIN
  SELECT string_agg(quote_ident(c.column_name), ',') INTO v_cols
    FROM information_schema.columns c
   WHERE c.table_schema = 'public' AND c.table_name = p_table AND p_row ? c.column_name
     AND c.is_generated = 'NEVER' AND c.identity_generation IS NULL;
  EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) RETURNING id', p_table, v_cols, v_cols, p_table)
    INTO v USING p_row;
  RETURN v;
END $_$;

-- @seq 349
CREATE FUNCTION public.app__row(p_table text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE j jsonb;
BEGIN
  IF to_regclass('public.' || quote_ident(p_table)) IS NULL THEN RAISE EXCEPTION 'Unknown table %', p_table; END IF;
  EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1', p_table) INTO j USING p_id;
  IF j IS NULL THEN RAISE EXCEPTION 'Record not found'; END IF;
  IF j->>'tenant_id' IS NULL THEN RAISE EXCEPTION 'Only tenant records support this action'; END IF;
  PERFORM acct_assert_access((j->>'tenant_id')::uuid);
  RETURN j;
END $_$;

-- @seq 350
CREATE FUNCTION public.app_archive_record(p_table text, p_id uuid, p_archive boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE j jsonb; v_set text[] := '{}';
BEGIN
  IF p_table = 'platform_parties' THEN
    j := app__row(p_table, p_id);
    UPDATE platform_parties SET metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('archived', p_archive, 'archived_at', CASE WHEN p_archive THEN now() END),
           updated_at = now() WHERE id = p_id;
    UPDATE crm_customers SET is_active = NOT p_archive, archived_at = CASE WHEN p_archive THEN now() END WHERE party_id = p_id;
    UPDATE acct_vendors SET is_active = NOT p_archive WHERE party_id = p_id;
    RETURN CASE WHEN p_archive THEN 'archived' ELSE 'active' END;
  END IF;
  j := app__row(p_table, p_id);
  IF j ? 'is_active'   THEN v_set := v_set || format('is_active = %L', NOT p_archive); END IF;
  IF j ? 'archived_at' THEN v_set := v_set || CASE WHEN p_archive THEN 'archived_at = now()' ELSE 'archived_at = NULL' END; END IF;
  IF p_table = 'products' THEN v_set := v_set || format('status = %L', CASE WHEN p_archive THEN 'archived' ELSE 'draft' END); END IF;
  IF cardinality(v_set) = 0 THEN RAISE EXCEPTION 'Archive is not available for %', p_table; END IF;
  IF j ? 'updated_at' THEN v_set := v_set || 'updated_at = now()'::text; END IF;
  EXECUTE format('UPDATE public.%I SET %s WHERE id = $1', p_table, array_to_string(v_set, ', ')) USING p_id;
  RETURN CASE WHEN p_archive THEN 'archived' ELSE 'active' END;
END $_$;

-- @seq 351
CREATE FUNCTION public.app_dashboard_overview(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_from date := coalesce(p_from, date_trunc('month', current_date)::date); v_to date := coalesce(p_to, current_date);
        v_len int; v_pfrom date; v_pto date; o jsonb; po jsonb; v_cash numeric; v_ar numeric; v_ap numeric; v_prod jsonb; v_sup jsonb; v_ch jsonb; v_inv numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_len := v_to - v_from + 1; v_pto := v_from - 1; v_pfrom := v_from - v_len;
  SELECT jsonb_build_object('gmv', coalesce(sum(total),0), 'orders', count(*), 'aov', round(coalesce(avg(total),0),2),
                            'refunds', coalesce(sum(amount_refunded),0), 'net_sales', coalesce(sum(total - coalesce(amount_refunded,0)),0),
                            'units', coalesce((SELECT sum(l.quantity) FROM erp_order_lines l JOIN erp_orders x ON x.id = l.order_id
                                               WHERE x.tenant_id = p_tenant_id AND x.status::text NOT IN ('cancelled','draft')
                                                 AND coalesce(x.order_date, x.created_at)::date BETWEEN v_from AND v_to),0),
                            'awaiting_fulfillment', count(*) FILTER (WHERE status::text IN ('confirmed','on_hold','allocated','partially_allocated','released','picking','partially_picked','packed','partially_shipped','backordered')))
    INTO o FROM erp_orders WHERE tenant_id = p_tenant_id AND status::text NOT IN ('cancelled','draft')
     AND coalesce(order_date, created_at)::date BETWEEN v_from AND v_to;
  SELECT jsonb_build_object('gmv', coalesce(sum(total),0), 'orders', count(*))
    INTO po FROM erp_orders WHERE tenant_id = p_tenant_id AND status::text NOT IN ('cancelled','draft')
     AND coalesce(order_date, created_at)::date BETWEEN v_pfrom AND v_pto;
  SELECT coalesce(jsonb_object_agg(ch, g), '{}'::jsonb) INTO v_ch FROM (
    SELECT coalesce(sales_channel, 'direct') ch, sum(total) g FROM erp_orders WHERE tenant_id = p_tenant_id AND status::text NOT IN ('cancelled','draft')
       AND coalesce(order_date, created_at)::date BETWEEN v_from AND v_to GROUP BY 1) s;
  SELECT jsonb_build_object('total', count(*), 'published', count(*) FILTER (WHERE status = 'published'), 'draft', count(*) FILTER (WHERE status = 'draft'),
                            'low_stock_variants', (SELECT count(*) FROM product_variants v WHERE v.tenant_id = p_tenant_id AND coalesce(v.is_active,true)
                                                     AND v.reorder_level IS NOT NULL AND coalesce(v.stock_quantity,0) <= v.reorder_level))
    INTO v_prod FROM products WHERE tenant_id = p_tenant_id;
  SELECT jsonb_build_object('open', count(*) FILTER (WHERE status::text NOT IN ('solved','closed','resolved')),
                            'breached', count(*) FILTER (WHERE status::text NOT IN ('solved','closed','resolved') AND (first_response_breached_at IS NOT NULL OR resolution_breached_at IS NOT NULL)),
                            'created_in_period', count(*) FILTER (WHERE created_at::date BETWEEN v_from AND v_to),
                            'csat', round(avg(csat_score) FILTER (WHERE csat_answered_at::date BETWEEN v_from AND v_to), 2))
    INTO v_sup FROM support_tickets WHERE tenant_id = p_tenant_id AND deleted_at IS NULL AND NOT coalesce(spam_flag, false);
  SELECT coalesce(sum(jl.debit - jl.credit),0) INTO v_cash
    FROM acct_journal_lines jl JOIN acct_journal_entries je ON je.id = jl.journal_entry_id
   WHERE je.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date <= v_to
     AND jl.account_id IN (SELECT gl_account_id FROM acct_bank_accounts WHERE tenant_id = p_tenant_id AND account_kind IN ('checking','savings','cash','money_market','payment_processor'));
  SELECT coalesce(sum(open_balance),0) INTO v_ar FROM acct_ar_invoices WHERE tenant_id = p_tenant_id AND posted_journal_id IS NOT NULL AND status <> 'void';
  SELECT coalesce(sum(open_balance),0) INTO v_ap FROM acct_ap_bills WHERE tenant_id = p_tenant_id AND posted_journal_id IS NOT NULL AND status <> 'void';
  -- inventory at cost is the ledger balance (the costing engine), units come from the ERP movement ledger
  SELECT coalesce(sum(jl.debit - jl.credit),0) INTO v_inv
    FROM acct_journal_lines jl JOIN acct_journal_entries je ON je.id = jl.journal_entry_id
   WHERE je.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date <= v_to
     AND jl.account_id IN (SELECT inventory_asset_account_id FROM acct_items WHERE tenant_id = p_tenant_id AND inventory_asset_account_id IS NOT NULL
                           UNION SELECT acct_role_account(p_tenant_id, acct_default_entity(p_tenant_id), 'inventory_asset', false));
  v_prod := v_prod || jsonb_build_object('units_on_hand', (SELECT coalesce(sum(on_hand),0) FROM erp_stock_levels WHERE tenant_id = p_tenant_id));
  RETURN jsonb_build_object(
    'period', jsonb_build_object('from', v_from, 'to', v_to, 'previous_from', v_pfrom, 'previous_to', v_pto),
    'sales', o || jsonb_build_object('gmv_previous', po->'gmv', 'orders_previous', po->'orders',
                                     'gmv_change_pct', CASE WHEN (po->>'gmv')::numeric > 0 THEN round(((o->>'gmv')::numeric / (po->>'gmv')::numeric - 1) * 100, 1) END,
                                     'by_channel', v_ch),
    'products', v_prod, 'support', v_sup,
    'finance', jsonb_build_object('cash', v_cash, 'accounts_receivable', v_ar, 'accounts_payable', v_ap, 'inventory_at_cost', v_inv));
END $$;

-- @seq 352
CREATE FUNCTION public.app_delete_draft(p_table text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE j jsonb; d platform_duplicable_tables%ROWTYPE;
BEGIN
  IF p_table NOT IN ('acct_ar_invoices','acct_estimates','acct_ap_bills','erp_purchase_orders','erp_orders','acct_ar_credit_memos','acct_statement_batches',
                     'acct_time_entries','products','cms_banners','cms_popups','crm_tasks','crm_notes','acct_payment_links') THEN
    RAISE EXCEPTION 'Delete is not available for %', p_table;
  END IF;
  j := app__row(p_table, p_id);
  IF j->>'posted_journal_id' IS NOT NULL THEN RAISE EXCEPTION 'Posted to the ledger: void it instead of deleting'; END IF;
  IF j ? 'status' AND p_table NOT IN ('crm_tasks','crm_notes','cms_banners','cms_popups','acct_time_entries')
     AND j->>'status' NOT IN ('draft','pending_review','open') THEN
    RAISE EXCEPTION 'Only drafts can be deleted (status is %)', j->>'status';
  END IF;
  IF p_table = 'erp_purchase_orders' AND EXISTS (SELECT 1 FROM erp_goods_receipts WHERE purchase_order_id = p_id) THEN
    RAISE EXCEPTION 'Items were received against this PO; cancel it instead';
  END IF;
  IF p_table = 'acct_time_entries' AND j->>'invoiced_line_id' IS NOT NULL THEN RAISE EXCEPTION 'Time entry is already invoiced'; END IF;
  SELECT * INTO d FROM platform_duplicable_tables WHERE table_name = p_table;
  IF d.child_table IS NOT NULL THEN EXECUTE format('DELETE FROM public.%I WHERE %I = $1', d.child_table, d.child_fk) USING p_id; END IF;
  EXECUTE format('DELETE FROM public.%I WHERE id = $1', p_table) USING p_id;
END $_$;

-- @seq 353
CREATE FUNCTION public.app_duplicate_record(p_table text, p_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE d platform_duplicable_tables%ROWTYPE; j jsonb; v uuid; c jsonb; k text;
        v_drop text[] := ARRAY['id','created_at','updated_at','posted_journal_id','posted_at','voided_at','voided_by','void_reason','approved_at',
                               'approved_by','open_balance','search_vector','row_version','deleted_at','archived_at','party_id'];
BEGIN
  SELECT * INTO d FROM platform_duplicable_tables WHERE table_name = p_table;
  IF NOT FOUND THEN RAISE EXCEPTION 'Duplicate is not available for %', p_table; END IF;
  j := app__row(p_table, p_id);
  FOREACH k IN ARRAY v_drop || d.reset_keys LOOP j := j - k; END LOOP;
  IF j ? 'status' THEN
    j := j || jsonb_build_object('status', CASE p_table WHEN 'products' THEN 'draft' WHEN 'crm_tasks' THEN 'open' WHEN 'erp_orders' THEN 'draft' ELSE 'draft' END);
  END IF;
  IF j ? 'name' AND p_table IN ('cms_banners','cms_popups','acct_items') THEN j := j || jsonb_build_object('name', (j->>'name') || ' (copy)'); END IF;
  IF j ? 'title' AND p_table IN ('crm_tasks') THEN j := j || jsonb_build_object('title', (j->>'title') || ' (copy)'); END IF;
  IF p_table = 'products' THEN
    j := j || jsonb_build_object('name', (j->>'name') || ' (copy)', 'slug', (j->>'slug') || '-copy-' || substr(replace(gen_random_uuid()::text,'-',''),1,6));
  END IF;
  IF p_table = 'commerce_coupons' THEN j := j || jsonb_build_object('code', upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), 'is_active', false); END IF;
  IF p_table = 'cms_banners' OR p_table = 'cms_popups' THEN j := j || jsonb_build_object('is_active', false); END IF;
  v := app__insert_json(p_table, j);
  IF d.child_table IS NOT NULL THEN
    FOR c IN EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I = $1', d.child_table, d.child_fk) USING p_id LOOP
      c := (c - ARRAY['id','created_at','updated_at','posted_journal_id','quantity_received','quantity_reserved','quantity_allocated','quantity_picked',
                      'quantity_packed','quantity_shipped','quantity_returned','invoiced_line_id','bill_line_id','erp_po_line_id'])
           || jsonb_build_object(d.child_fk, v);
      IF p_table = 'products' THEN c := c || jsonb_build_object('sku', (c->>'sku') || '-COPY-' || substr(replace(gen_random_uuid()::text,'-',''),1,4)); END IF;
      PERFORM app__insert_json(d.child_table, c);
    END LOOP;
  END IF;
  -- documents recompute totals from their copied lines
  IF p_table = 'acct_ar_invoices' THEN PERFORM acct_invoice_recalc(v); END IF;
  RETURN v;
END $_$;

-- @seq 354
CREATE FUNCTION public.app_publish_product(p_product_id uuid, p_publish boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p products%ROWTYPE;
BEGIN
  SELECT * INTO p FROM products WHERE id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Product not found'; END IF;
  PERFORM acct_assert_access(p.tenant_id);
  IF p_publish THEN
    IF NOT EXISTS (SELECT 1 FROM product_variants WHERE product_id = p.id AND coalesce(is_active, true) AND price > 0) THEN
      RAISE EXCEPTION 'Add at least one active, priced variant before publishing';
    END IF;
    UPDATE products SET status = 'published', published_at = coalesce(published_at, now()), updated_at = now() WHERE id = p.id;
    RETURN 'published';
  END IF;
  UPDATE products SET status = 'draft', updated_at = now() WHERE id = p.id;
  RETURN 'draft';
END $$;

-- @seq 355
CREATE FUNCTION public.app_reprice_variants(p_variant_ids uuid[], p_price numeric DEFAULT NULL::numeric, p_percent numeric DEFAULT NULL::numeric, p_set_compare_at boolean DEFAULT false, p_round_to_99 boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid; n int;
BEGIN
  IF (p_price IS NULL) = (p_percent IS NULL) THEN RAISE EXCEPTION 'Give either a new price or a percent change'; END IF;
  FOR v_t IN SELECT DISTINCT tenant_id FROM product_variants WHERE id = ANY(p_variant_ids) LOOP PERFORM acct_assert_access(v_t); END LOOP;
  UPDATE product_variants v SET
         compare_at_price = CASE WHEN p_set_compare_at THEN v.price ELSE v.compare_at_price END,
         price = greatest(0.01, CASE WHEN p_round_to_99 THEN floor(x.np) + 0.99 ELSE round(x.np, 2) END),
         updated_at = now()
    FROM (SELECT id, coalesce(p_price, price * (1 + p_percent / 100)) np FROM product_variants WHERE id = ANY(p_variant_ids)) x
   WHERE v.id = x.id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- @seq 356
CREATE FUNCTION public.app_void(p_doc_type text, p_id uuid, p_reason text, p_date date DEFAULT NULL::date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  CASE p_doc_type
    WHEN 'invoice', 'sales_receipt' THEN PERFORM acct_void_invoice(p_id, p_reason, p_date);
    WHEN 'receipt'        THEN PERFORM acct_void_receipt(p_id, p_reason);
    WHEN 'credit_memo'    THEN PERFORM acct_void_credit_memo(p_id, p_reason, p_date);
    WHEN 'bill_payment'   THEN PERFORM acct_void_bill_payment(p_id, p_reason, p_date);
    WHEN 'transfer'       THEN PERFORM acct_void_transfer(p_id, p_reason, p_date);
    WHEN 'settlement'     THEN PERFORM acct_reverse_channel_settlement(p_id, coalesce(p_date, current_date), p_reason);
    WHEN 'journal'        THEN PERFORM acct_reverse_journal(p_id, coalesce(p_date, current_date), 'Void: ' || p_reason);
    WHEN 'order'          THEN PERFORM erp_cancel_order(p_id, p_reason);
    WHEN 'deposit'        THEN PERFORM acct_void_deposit(p_id, p_reason, p_date);
    WHEN 'bill', 'spend', 'vendor_credit', 'check'
                          THEN PERFORM acct_void_document(p_doc_type, p_id, p_reason, p_date);
    ELSE RAISE EXCEPTION 'Void is not available for %', p_doc_type;
  END CASE;
  RETURN 'void';
END $$;

-- @seq 387
CREATE FUNCTION public.current_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  -- the active tenant only counts if the user is still an active member of it
  SELECT p.active_tenant_id
    FROM public.profiles p
   WHERE p.id = auth.uid()
     AND (public.platform_is_admin() OR EXISTS (
          SELECT 1 FROM public.tenant_memberships tm
           WHERE tm.tenant_id = p.active_tenant_id AND tm.user_id = auth.uid()
             AND tm.active AND tm.status = 'active'));
$$;

-- @seq 388
CREATE FUNCTION public.current_tenant_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT tenant_id FROM public.tenant_memberships
   WHERE user_id = auth.uid() AND active AND status = 'active';
$$;

