-- @seq 486
CREATE FUNCTION public.platform__apply_app_security() RETURNS TABLE(table_name text, access_mode text, action text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g record; p record; v_pred text; v_wpred text; v_t text; v_left int; v_explicit boolean;
BEGIN
  PERFORM platform_classify_tables();

  FOR g IN SELECT * FROM platform_table_registry r
            WHERE to_regclass('public.' || quote_ident(r.table_name)) IS NOT NULL
            ORDER BY r.table_name
  LOOP
    v_t := g.table_name;
    v_explicit := g.mode_source = 'explicit';
    -- the registry tables are open in this loop; their RLS is enabled once at the end of the file
    IF v_t NOT IN ('platform_table_registry','platform_table_access_overrides') THEN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_t);
    END IF;

    -- acct_* tables keep the part-6 rules (acct__apply_security); only their audit matters here
    IF v_t LIKE 'acct\_%' THEN CONTINUE; END IF;

    -- 1. drop unsafe policies everywhere
    FOR p IN SELECT pp.policyname, pp.qual, pp.with_check, pp.roles FROM pg_policies pp
              WHERE pp.schemaname = 'public' AND pp.tablename = v_t LOOP
      IF (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~* 'current_setting\(.app\.current_tenant_id.*IS NULL'
         OR ((coalesce(p.qual,'') = 'true' OR coalesce(p.with_check,'') = 'true')
             AND g.access_mode NOT IN ('global_read','public_read')
             AND NOT (p.roles = ARRAY['service_role']::name[]))
         OR (v_explicit AND p.policyname NOT LIKE 'app\_%') THEN
        EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, v_t);
        table_name := v_t; access_mode := g.access_mode; action := 'dropped policy ' || p.policyname; RETURN NEXT;
      END IF;
    END LOOP;

    -- 2. our own policies are always rebuilt
    FOR p IN SELECT pp.policyname FROM pg_policies pp
              WHERE pp.schemaname='public' AND pp.tablename = v_t AND pp.policyname LIKE 'app\_%' LOOP
      EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, v_t);
    END LOOP;

    -- 3. keep existing (safe) policies for inferred tables; add ours only where none remain
    SELECT count(*) INTO v_left FROM pg_policies pp WHERE pp.schemaname='public' AND pp.tablename = v_t;

    IF g.access_mode <> 'service_only' THEN
      EXECUTE format('CREATE POLICY app_platform_admin ON public.%I FOR ALL TO authenticated USING (public.platform_is_admin()) WITH CHECK (public.platform_is_admin())', v_t);
    END IF;

    IF v_left > 0 AND NOT v_explicit THEN
      table_name := v_t; access_mode := g.access_mode; action := 'kept existing policies'; RETURN NEXT;
      CONTINUE;
    END IF;

    CASE g.access_mode
      WHEN 'service_only' THEN
        EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', v_t);
      WHEN 'admin_only' THEN
        EXECUTE format('REVOKE ALL ON public.%I FROM anon', v_t);
        IF platform__has_col(v_t, 'user_id') AND v_t = 'platform_admins' THEN
          EXECUTE format('CREATE POLICY app_self_read ON public.%I FOR SELECT TO authenticated USING (user_id = auth.uid())', v_t);
        END IF;
      WHEN 'global_read' THEN
        EXECUTE format('REVOKE ALL ON public.%I FROM anon', v_t);
        EXECUTE format('CREATE POLICY app_global_read ON public.%I FOR SELECT TO authenticated USING (true)', v_t);
      WHEN 'public_read' THEN
        EXECUTE format('GRANT SELECT ON public.%I TO anon', v_t);
        EXECUTE format('CREATE POLICY app_public_read ON public.%I FOR SELECT TO anon, authenticated USING (true)', v_t);
      ELSE
        v_pred := platform__row_predicate(v_t, v_t, 0, false);
        IF v_pred IS NULL THEN
          table_name := v_t; access_mode := g.access_mode; action := 'UNRESOLVED: no tenant path'; RETURN NEXT;
          CONTINUE;
        END IF;
        EXECUTE format('REVOKE ALL ON public.%I FROM anon', v_t);
        EXECUTE format('CREATE POLICY app_member_read ON public.%I FOR SELECT TO authenticated USING (%s)', v_t, v_pred);
        IF g.access_mode IN ('tenant','child','user','self') THEN
          EXECUTE format('CREATE POLICY app_member_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (%s)', v_t, v_pred);
          EXECUTE format('CREATE POLICY app_member_update ON public.%I FOR UPDATE TO authenticated USING (%s) WITH CHECK (%s)', v_t, v_pred, v_pred);
          EXECUTE format('CREATE POLICY app_member_delete ON public.%I FOR DELETE TO authenticated USING (%s)', v_t, v_pred);
        ELSIF g.access_mode = 'tenant_admin' THEN
          v_wpred := platform__row_predicate(v_t, v_t, 0, true);
          EXECUTE format('CREATE POLICY app_admin_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (%s)', v_t, v_wpred);
          EXECUTE format('CREATE POLICY app_admin_update ON public.%I FOR UPDATE TO authenticated USING (%s) WITH CHECK (%s)', v_t, v_wpred, v_wpred);
          EXECUTE format('CREATE POLICY app_admin_delete ON public.%I FOR DELETE TO authenticated USING (%s)', v_t, v_wpred);
        END IF;
        -- tenant_read / child_read / tenant_self: read only for members
      END CASE;
    table_name := v_t; access_mode := g.access_mode; action := 'applied ' || g.access_mode; RETURN NEXT;
  END LOOP;

  -- partitions inherit nothing from the parent: lock them; clients query the parent
  FOR p IN SELECT c.relname FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p') AND c.relispartition LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', p.relname);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', p.relname);
  END LOOP;
END $$;

-- @seq 487
CREATE FUNCTION public.platform__apply_canonical_map() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE n int;
BEGIN
  UPDATE platform_table_registry g
     SET lifecycle = CASE WHEN g.lifecycle = 'archived' THEN 'archived'
                          WHEN m.relation = 'legacy' THEN 'legacy'
                          WHEN g.lifecycle = 'legacy' THEN 'active' ELSE g.lifecycle END,
         canonical_table = m.canonical_table,
         notes = coalesce(m.notes, g.notes)
    FROM platform_canonical_map m WHERE m.legacy_table = g.table_name;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- @seq 488
CREATE FUNCTION public.platform__assert_tenant_admin(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF NOT (coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
          OR current_user IN ('postgres','supabase_admin')
          OR platform_is_admin() OR platform_is_tenant_admin(p_tenant_id)) THEN
    RAISE EXCEPTION 'Tenant admins only';
  END IF;
END $$;

-- @seq 489
CREATE FUNCTION public.platform__can_see_task(p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (SELECT 1 FROM crm_tasks t WHERE t.id = p_task_id AND platform_is_tenant_member(t.tenant_id)
                   AND (t.visibility = 'team' OR t.created_by = auth.uid() OR t.assigned_to = auth.uid()
                        OR EXISTS (SELECT 1 FROM crm_task_assignees a WHERE a.task_id = t.id AND a.user_id = auth.uid())))
      OR platform_is_admin();
$$;

-- @seq 490
CREATE FUNCTION public.platform__ensure_fk(p_child text, p_col text, p_parent text, p_parent_col text DEFAULT 'id'::text, p_on_delete text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_child regclass := to_regclass('public.' || quote_ident(p_child));
  v_parent regclass := to_regclass('public.' || quote_ident(p_parent));
  v_ct text; v_pt text; v_notnull boolean; v_name text; v_status text; v_orphans bigint; v_del text; v_detail text := p_note;
  v_attnum int2; v_pattnum int2;
BEGIN
  IF v_child IS NULL OR v_parent IS NULL THEN
    v_status := 'missing';
  ELSE
    SELECT a.attnum, format_type(a.atttypid, a.atttypmod), a.attnotnull INTO v_attnum, v_ct, v_notnull
      FROM pg_attribute a WHERE a.attrelid = v_child AND a.attname = p_col AND NOT a.attisdropped;
    SELECT a.attnum, format_type(a.atttypid, a.atttypmod) INTO v_pattnum, v_pt
      FROM pg_attribute a WHERE a.attrelid = v_parent AND a.attname = p_parent_col AND NOT a.attisdropped;
    IF v_attnum IS NULL OR v_pattnum IS NULL THEN
      v_status := 'missing';
    ELSIF EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid = v_child AND c.contype = 'f'
                   AND c.conkey = ARRAY[v_attnum] AND c.confrelid = v_parent) THEN
      v_status := 'exists';
      SELECT c.conname INTO v_name FROM pg_constraint c WHERE c.conrelid = v_child AND c.contype = 'f'
         AND c.conkey = ARRAY[v_attnum] AND c.confrelid = v_parent LIMIT 1;
    ELSIF v_ct <> v_pt THEN
      v_status := 'type_mismatch';
      v_detail := concat_ws('; ', v_detail, format('%s.%s is %s, %s.%s is %s', p_child, p_col, v_ct, p_parent, p_parent_col, v_pt));
    ELSIF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = v_parent AND (i.indisprimary OR i.indisunique)
                       AND i.indpred IS NULL AND i.indnkeyatts = 1 AND i.indkey[0] = v_pattnum) THEN
      v_status := 'no_unique_target';
    ELSE
      v_del := coalesce(p_on_delete, CASE WHEN v_notnull THEN 'NO ACTION' ELSE 'SET NULL' END);
      v_name := p_child || '_' || p_col || '_fk';
      IF length(v_name) > 63 THEN v_name := left(v_name, 54) || '_' || left(md5(v_name), 8); END IF;
      BEGIN
        EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES public.%I(%I) ON DELETE %s NOT VALID',
                       p_child, v_name, p_col, p_parent, p_parent_col, v_del);
        BEGIN
          EXECUTE format('ALTER TABLE public.%I VALIDATE CONSTRAINT %I', p_child, v_name);
          v_status := 'validated';
        EXCEPTION WHEN foreign_key_violation THEN
          EXECUTE format('SELECT count(*) FROM public.%I c WHERE c.%I IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.%I p WHERE p.%I = c.%I)',
                         p_child, p_col, p_parent, p_parent_col, p_col) INTO v_orphans;
          v_status := 'not_valid_orphans';
        END;
      EXCEPTION WHEN OTHERS THEN
        v_status := 'error'; v_detail := concat_ws('; ', v_detail, SQLERRM);
      END;
    END IF;
  END IF;
  INSERT INTO platform_fk_log AS l (child_table, child_column, parent_table, constraint_name, status, orphan_rows, detail, logged_at)
  VALUES (p_child, p_col, p_parent, v_name, v_status, v_orphans, v_detail, now())
  ON CONFLICT (child_table, child_column) DO UPDATE
    SET parent_table = EXCLUDED.parent_table,
        constraint_name = coalesce(EXCLUDED.constraint_name, l.constraint_name),
        -- re-running keeps the original outcome (orphans) visible instead of overwriting it with 'exists'
        status = CASE WHEN EXCLUDED.status = 'exists' AND l.status IN ('validated','not_valid_orphans') THEN l.status ELSE EXCLUDED.status END,
        orphan_rows = coalesce(EXCLUDED.orphan_rows, l.orphan_rows),
        detail = coalesce(EXCLUDED.detail, l.detail), logged_at = now();
  RETURN v_status;
END $$;

-- @seq 491
CREATE FUNCTION public.platform__has_col(p_table text, p_col text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM pg_attribute a
                  WHERE a.attrelid = to_regclass('public.' || quote_ident(p_table))
                    AND a.attname = p_col AND a.attnum > 0 AND NOT a.attisdropped);
$$;

-- @seq 492
CREATE FUNCTION public.platform__is_chat_member(p_thread_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (SELECT 1 FROM platform_chat_members m JOIN platform_chat_threads t ON t.id = m.thread_id
                  WHERE m.thread_id = p_thread_id AND m.user_id = auth.uid() AND platform_is_tenant_member(t.tenant_id));
$$;

-- @seq 493
CREATE FUNCTION public.platform__parent_fk(p_table text, OUT parent_table text, OUT parent_column text) RETURNS record
    LANGUAGE sql STABLE
    AS $_$
  SELECT t.relname::text, a.attname::text
    FROM pg_constraint k
    JOIN pg_class s ON s.oid = k.conrelid
    JOIN pg_class t ON t.oid = k.confrelid
    JOIN pg_namespace tn ON tn.oid = t.relnamespace
    JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = k.conkey[1]
   WHERE s.relname = p_table AND s.relnamespace = 'public'::regnamespace
     AND tn.nspname = 'public' AND k.contype = 'f' AND array_length(k.conkey,1) = 1
     AND t.relname <> p_table AND t.relname <> 'tenants'
   ORDER BY (position(regexp_replace(t.relname, '(e?s)$', '') IN s.relname) = 1) DESC,   -- bill_items -> bills
            (public.platform__has_col(t.relname, 'tenant_id')) DESC,
            (a.attname ~ '(order|invoice|bill|campaign|case|seller|product|ticket|session|account|report|run|batch|contract|lease|budget|asset|allocation|estimate|import|cart|sale|refund|subscription|plan|payment|location|design|slot|page|module|advertiser|organization|supplier|attribute|node|experiment|creative|group|filter|gift_card|loyalty|store_credit|coupon|promotion|contact)_id$') DESC,
            a.attname
   LIMIT 1;
$_$;

-- @seq 494
CREATE FUNCTION public.platform__party_assign_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s platform_party_sources; j jsonb := to_jsonb(NEW); k text; v_name text; v_kind text := 'person'; v_party uuid;
BEGIN
  IF j->>'party_id' IS NOT NULL OR j->>'tenant_id' IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO s FROM platform_party_sources WHERE table_name = TG_TABLE_NAME;
  IF NOT FOUND THEN RETURN NEW; END IF;
  FOREACH k IN ARRAY s.name_keys LOOP
    v_name := coalesce(v_name, nullif(btrim(j->>k), ''));
  END LOOP;
  v_name := coalesce(v_name, nullif(btrim(concat_ws(' ', j->>s.first_key, j->>s.last_key)), ''));
  IF nullif(btrim(j->>s.first_key), '') IS NULL THEN
    FOREACH k IN ARRAY s.org_keys LOOP
      IF nullif(btrim(j->>k), '') IS NOT NULL THEN v_kind := 'organization'; END IF;
    END LOOP;
  END IF;
  v_party := platform__party_resolve((j->>'tenant_id')::uuid, v_name, j->>s.email_key, j->>s.phone_key, v_kind);
  NEW := jsonb_populate_record(NEW, jsonb_build_object('party_id', v_party));
  RETURN NEW;
END $$;

-- @seq 495
CREATE FUNCTION public.platform__party_resolve(p_tenant uuid, p_name text, p_email text, p_phone text, p_kind text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_email text := nullif(lower(btrim(p_email)), ''); v_id uuid;
BEGIN
  IF p_tenant IS NULL THEN RETURN NULL; END IF;
  IF v_email IS NOT NULL THEN
    SELECT id INTO v_id FROM platform_parties WHERE tenant_id = p_tenant AND email_normalized = v_email AND merged_into_id IS NULL;
    IF FOUND THEN RETURN v_id; END IF;
  END IF;
  INSERT INTO platform_parties (tenant_id, party_kind, display_name, email_normalized, phone)
  VALUES (p_tenant, coalesce(p_kind, 'person'), nullif(btrim(p_name), ''), v_email, nullif(btrim(p_phone), ''))
  ON CONFLICT (tenant_id, email_normalized) WHERE email_normalized IS NOT NULL AND merged_into_id IS NULL
  DO UPDATE SET updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;

-- @seq 496
CREATE FUNCTION public.platform__row_predicate(p_table text, p_alias text, p_depth integer DEFAULT 0, p_admin_write boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g record; v_pa text := 'p' || p_depth; v_inner text;
BEGIN
  IF p_depth > 4 THEN RETURN NULL; END IF;
  SELECT * INTO g FROM platform_table_registry WHERE table_name = p_table;
  IF platform__has_col(p_table, 'tenant_id') AND (g.access_mode IS NULL OR g.access_mode NOT IN ('child','child_read')) THEN
    IF p_admin_write THEN RETURN format('public.platform_is_tenant_admin(%s.tenant_id)', p_alias); END IF;
    RETURN format('public.platform_is_tenant_member(%s.tenant_id)', p_alias);
  END IF;
  IF g.access_mode = 'user' THEN RETURN format('%s.user_id = auth.uid()', p_alias); END IF;
  IF g.access_mode = 'self' THEN RETURN format('%s.id = auth.uid()', p_alias); END IF;
  IF g.access_mode = 'tenant_self' THEN RETURN format('public.platform_is_tenant_member(%s.id)', p_alias); END IF;
  IF g.parent_table IS NULL THEN RETURN NULL; END IF;
  v_inner := platform__row_predicate(g.parent_table, v_pa, p_depth + 1, p_admin_write);
  IF v_inner IS NULL THEN RETURN NULL; END IF;
  RETURN format('EXISTS (SELECT 1 FROM public.%I %s WHERE %s.id = %s.%I AND %s)',
                g.parent_table, v_pa, v_pa, p_alias, g.parent_column, v_inner);
END $$;

-- @seq 497
CREATE FUNCTION public.platform__secure_feature_functions() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f record; v_sig text; n int := 0;
BEGIN
  FOR f IN SELECT p.oid, p.proname, p.prosecdef, p.prosrc, pg_get_function_result(p.oid) res FROM pg_proc p
            WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f' AND p.proname = ANY(ARRAY['erp__default_warehouse','erp__default_location','erp__sku_for_item','erp__sku_for_variant','erp_movement_stock_trg','acct__inv_mirror','erp__move','erp__order_status','erp_cancel_order','erp_add_order_note','erp_mark_shipped','erp_record_tracking_event','erp_send_purchase_order','erp_receive_purchase_order','erp_adjust_stock','erp_transfer_stock','erp_receive_transfer','erp_stock_history','erp_decide_return','erp_set_carrier_active','acct__ensure_account','app__default_from','acct_setup_channel','acct_import_channel_settlement','acct_post_channel_settlement','acct_reverse_channel_settlement','acct_transfer_funds','acct_void_transfer','acct_create_statement_batch','acct_generate_statement_batch','acct_send_statement','acct_send_statement_batch','acct_duplicate_statement_batch','acct_time_entry_unlink_trg','acct_invoice_unbilled_time','acct_unbilled_time','platform__can_see_task','platform__is_chat_member','platform_create_task','platform_move_task','platform_start_chat','platform_post_message','platform_mark_chat_read','platform_my_inbox','cap_events_immutable_trg','cap__months','cap_vested_shares','cap_table','cap_model_round','cap__equity_accounts','cap__event','cap_available_shares','cap_issue_shares','cap_grant_options','cap_exercise_option','cap_cancel_options','cap_record_convertible','cap_close_round','cap_liquidation_waterfall','cap_controls_check','acct_create_credit_memo','acct_post_credit_memo','acct_apply_credit_memo','acct_void_credit_memo','acct_send_invoice','acct_mark_invoice_paid','acct_create_payment_link','app_publish_product','app_reprice_variants','erp_refund_order','erp_open_return','erp_receive_return','platform_party_add_role','platform_action_coverage','app__row','app__insert_json','app_duplicate_record','app_archive_record','app_delete_draft','acct_void_deposit','app_void','app_dashboard_overview']) LOOP
    v_sig := f.oid::regprocedure::text;
    EXECUTE 'REVOKE ALL ON FUNCTION ' || v_sig || ' FROM PUBLIC, anon';
    EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO service_role';
    IF f.proname IN ('platform__can_see_task','platform__is_chat_member','platform_mark_chat_read','platform_action_coverage','app_void') THEN
      -- RLS policy predicates (must be callable by app users; return a boolean about auth.uid() only),
      -- the caller-scoped chat read marker, global action metadata, and the void dispatcher (each target checks access)
      EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO authenticated';
    ELSIF f.proname IN ('cap_vested_shares','cap_available_shares') THEN
      EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
    ELSIF f.res = 'trigger' OR f.proname LIKE '%\_\_%' THEN
      EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
    ELSIF NOT f.prosecdef OR f.prosrc ~ '(acct_assert_access|platform__assert_tenant_admin|platform_is_tenant_member|platform_is_tenant_admin|platform__can_see_task|platform__is_chat_member|app__row|service_role)' THEN
      EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO authenticated';
    ELSE
      EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
      RAISE NOTICE 'service-only (no access check found): %', v_sig;
    END IF;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- @seq 498
CREATE FUNCTION public.platform__secure_mef_functions() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f record; v_sig text; n int := 0;
  v_worker text[] := ARRAY['mef_claim','mef_record_transmission','mef_record_transmission_failure','mef_record_ack',
                           'mef_new_submission_id','mef_new_message_id','mef_set_environment','mef_readiness'];
BEGIN
  FOR f IN SELECT p.oid, p.proname, p.prosecdef, p.prosrc, pg_get_function_result(p.oid) res FROM pg_proc p
            WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f'
              AND (p.proname LIKE 'mef\_%' OR p.proname LIKE 'tax\_consent%' OR p.proname LIKE 'tax\_\_%'
                   OR p.proname IN ('efile_build_payroll_filing','efile_queue','platform__vault_store','platform__secure_mef_functions')) LOOP
    v_sig := f.oid::regprocedure::text;
    EXECUTE 'REVOKE ALL ON FUNCTION ' || v_sig || ' FROM PUBLIC, anon';
    EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO service_role';
    IF f.proname = ANY (v_worker) OR f.proname = 'platform__secure_mef_functions' OR f.res = 'trigger' OR f.proname LIKE '%\_\_%' THEN
      EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
    ELSIF f.prosecdef AND f.prosrc ~ '(acct_assert_access|platform__assert_tenant_admin|platform_is_tenant_member|platform_is_tenant_admin)' THEN
      EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO authenticated';
    ELSE
      EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
      RAISE NOTICE 'service-only (no access check found): %', v_sig;
    END IF;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- @seq 499
CREATE FUNCTION public.platform__table_domain(p_table text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN p_table ~ '^acct_' THEN 'finance'
    WHEN p_table ~ '^(bills?|bill_items|invoices?|invoice_|estimates?|estimate_items|receipts?|receipt_items|journal_|chart_of_accounts|bank_|reconciliation|taxes|tax_|vendor_invoice|recurring_invoice|customer_statements|payroll_)' THEN 'finance_legacy'
    WHEN p_table ~ '^(erp_|inventory_|purchase_order|goods_receipt|fulfillment_|warehouse)' THEN 'operations'
    WHEN p_table ~ '^(commerce_|orders$|order_|ecommerce_|sales_order|cart|checkout|promo|offers?$|gift)' THEN 'commerce'
    WHEN p_table ~ '^(products?|product_|catalog|categor|collections?|brands?|attribute|variant|taxonomy|node_|canonical_|shop_)' THEN 'catalog'
    WHEN p_table ~ '^(crm_|customers?$|customer_|portal_|perk|membership)' THEN 'crm'
    WHEN p_table ~ '^(support_)' THEN 'support'
    WHEN p_table ~ '^(seller_|sellers$)' THEN 'marketplace'
    WHEN p_table ~ '^(supplier|suppl|dropship|vendors?$)' THEN 'supply'
    WHEN p_table ~ '^(social_|ugc_)' THEN 'social'
    WHEN p_table ~ '^(ad_|licensee_|ssp_)' THEN 'advertising'
    WHEN p_table ~ '^(cms_|page_|site_|seo_|route_|related_search|merchandising|theme_)' THEN 'content'
    WHEN p_table ~ '^(ai_)' THEN 'ai'
    WHEN p_table ~ '^(design|printfile)' THEN 'studio'
    WHEN p_table ~ '^(platform_|tenant|profiles|user_|app_|api_keys|identity_|organizations|admin_)' THEN 'platform'
    WHEN p_table ~ '^(integration_|sync_|provider_|oauth|stripe_|paypal_|google_|teller_|resend_|efile_)' THEN 'integrations'
    WHEN p_table ~ '^(marketing_|email_|newsletter|campaign)' THEN 'marketing'
    WHEN p_table ~ '^(cap_|captable|equity_|409a)' THEN 'cap_table'
    ELSE 'other' END;
$_$;

-- @seq 500
CREATE FUNCTION public.platform__vault_store(p_name text, p_secret text, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'vault' AND p.proname = 'create_secret') THEN
    RAISE EXCEPTION 'Supabase Vault is not available; PINs cannot be stored';
  END IF;
  EXECUTE 'SELECT vault.create_secret($1, $2, $3)' INTO v USING p_secret, p_name || ':' || gen_random_uuid()::text, p_description;
  RETURN v;
END $_$;

-- @seq 501
CREATE FUNCTION public.platform_action_coverage() RETURNS TABLE(action_code text, display_name text, implementation text, binding text, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT a.action_code, a.display_name, a.implementation, coalesce(a.rpc_function, a.target_table),
         CASE
           WHEN a.rpc_function IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = a.rpc_function)
             THEN 'missing_function'
           WHEN a.rpc_function IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = a.rpc_function
                                                             AND has_function_privilege('authenticated', p.oid, 'EXECUTE'))
             THEN 'not_executable_by_users'
           WHEN a.target_table IS NOT NULL AND to_regclass('public.' || quote_ident(a.target_table)) IS NULL THEN 'missing_table'
           WHEN a.target_table IS NOT NULL AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass('public.' || quote_ident(a.target_table)))
             THEN 'table_without_rls'
           WHEN a.implementation = 'table' AND NOT EXISTS (SELECT 1 FROM pg_policy pol WHERE pol.polrelid = to_regclass('public.' || quote_ident(a.target_table))
                                                             AND pol.polcmd IN ('a','*'))
             THEN 'no_insert_policy'
           ELSE 'ok' END
    FROM platform_quick_action_registry a WHERE a.is_active ORDER BY a.sort_order, a.action_code;
$$;

-- @seq 502
CREATE FUNCTION public.platform_archive_legacy_table(p_table text, p_confirm text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g platform_table_registry; v_dep text;
BEGIN
  IF NOT (platform_is_admin() OR coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
          OR current_user IN ('postgres','supabase_admin')) THEN
    RAISE EXCEPTION 'Platform admins only';
  END IF;
  SELECT * INTO g FROM platform_table_registry WHERE table_name = p_table;
  IF NOT FOUND OR g.lifecycle <> 'legacy' THEN RAISE EXCEPTION '% is not marked legacy', p_table; END IF;
  IF p_confirm IS DISTINCT FROM 'ARCHIVE ' || p_table THEN
    RAISE EXCEPTION 'Confirm by passing the text: ARCHIVE %', p_table;
  END IF;
  SELECT string_agg(DISTINCT f.conrelid::regclass::text, ', ') INTO v_dep
    FROM pg_constraint f LEFT JOIN platform_table_registry ch ON ch.table_name = f.conrelid::regclass::text
   WHERE f.contype = 'f' AND f.confrelid = to_regclass('public.' || quote_ident(p_table)) AND f.conrelid <> f.confrelid
     AND coalesce(ch.lifecycle, 'active') NOT IN ('legacy','archived');
  IF v_dep IS NOT NULL THEN
    RAISE EXCEPTION 'Active tables still reference %: %', p_table, v_dep;
  END IF;
  EXECUTE format('ALTER TABLE public.%I SET SCHEMA archive', p_table);
  EXECUTE format('REVOKE ALL ON archive.%I FROM anon, authenticated', p_table);
  UPDATE platform_table_registry SET lifecycle = 'archived', notes = concat_ws('; ', notes, 'archived ' || now()::date) WHERE table_name = p_table;
  RETURN 'archive.' || p_table;
END $$;

-- @seq 503
CREATE FUNCTION public.platform_classify_tables() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE r record; v_mode text; v_src text; v_pt text; v_pc text; v_life text; v_note text; n int := 0;
BEGIN
  FOR r IN
    SELECT c.relname::text AS t
      FROM pg_class c
     WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p') AND NOT c.relispartition
  LOOP
    v_pt := NULL; v_pc := NULL; v_src := 'inferred'; v_life := NULL; v_note := NULL;
    SELECT o.access_mode, o.lifecycle, o.notes INTO v_mode, v_life, v_note
      FROM platform_table_access_overrides o WHERE o.table_name = r.t;
    IF FOUND THEN
      v_src := 'explicit';
    ELSIF platform__has_col(r.t, 'tenant_id') THEN
      v_mode := 'tenant';
    ELSIF platform__has_col(r.t, 'user_id') AND NOT EXISTS (
            SELECT 1 FROM platform__parent_fk(r.t) f WHERE position(regexp_replace(f.parent_table, '(e?s)$', '') IN r.t) = 1) THEN
      v_mode := 'user';
    ELSE
      SELECT f.parent_table, f.parent_column INTO v_pt, v_pc FROM platform__parent_fk(r.t) f;
      IF v_pt IS NOT NULL THEN
        v_mode := 'child';
      ELSIF platform__has_col(r.t, 'user_id') THEN
        v_mode := 'user';
      ELSE
        v_mode := 'admin_only';
        v_note := 'no tenant, parent or owner column: platform admins only until classified';
      END IF;
    END IF;
    IF v_mode IN ('child','child_read') AND v_pt IS NULL THEN
      SELECT f.parent_table, f.parent_column INTO v_pt, v_pc FROM platform__parent_fk(r.t) f;
    END IF;

    INSERT INTO platform_table_registry AS g (table_name, domain, access_mode, mode_source, parent_table, parent_column, lifecycle, notes, classified_at)
    VALUES (r.t, platform__table_domain(r.t), v_mode, v_src, v_pt, v_pc,
            coalesce(v_life, CASE WHEN r.t ~ '(_log|_events|_attempts|_deliveries|_history)$' THEN 'log' ELSE 'active' END),
            v_note, now())
    ON CONFLICT (table_name) DO UPDATE
      SET domain = EXCLUDED.domain, access_mode = EXCLUDED.access_mode, mode_source = EXCLUDED.mode_source,
          parent_table = EXCLUDED.parent_table, parent_column = EXCLUDED.parent_column,
          lifecycle = CASE WHEN g.lifecycle IN ('legacy','archived') THEN g.lifecycle ELSE EXCLUDED.lifecycle END,
          notes = coalesce(EXCLUDED.notes, g.notes), classified_at = now();
    n := n + 1;
  END LOOP;
  DELETE FROM platform_table_registry g
   WHERE to_regclass('public.' || quote_ident(g.table_name)) IS NULL AND g.lifecycle <> 'archived';
  RETURN n;
END $_$;

-- @seq 504
CREATE FUNCTION public.platform_create_task(p_tenant_id uuid, p_title text, p_description text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_assignees uuid[] DEFAULT NULL::uuid[], p_related_type text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'normal'::text, p_visibility text DEFAULT 'team'::text, p_task_type text DEFAULT 'todo'::text, p_module text DEFAULT NULL::text, p_board_column text DEFAULT NULL::text, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v uuid; u uuid; v_cust uuid; v_type text; v_table text; v_ok boolean;
BEGIN
  IF NOT (platform_is_tenant_member(p_tenant_id) OR auth.role() = 'service_role') THEN RAISE EXCEPTION 'Not a member of this company' USING ERRCODE = '42501'; END IF;
  IF p_title IS NULL OR btrim(p_title) = '' THEN RAISE EXCEPTION 'Task title is required'; END IF;
  IF p_related_type IS NOT NULL THEN
    -- accept the type name ('order') or the table name ('erp_orders'); store the canonical type value
    SELECT type_value, target_table INTO v_type, v_table FROM platform_polymorphic_type_map
     WHERE type_value = p_related_type OR target_table = p_related_type
     ORDER BY (type_value = p_related_type) DESC, type_value LIMIT 1;
    IF v_type IS NULL THEN RAISE EXCEPTION 'Unknown record type % for a task link', p_related_type; END IF;
    IF p_related_id IS NULL THEN RAISE EXCEPTION 'Pick the % this task is about', v_type; END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE id = $1 AND tenant_id = $2)', v_table) INTO v_ok USING p_related_id, p_tenant_id;
    IF NOT v_ok THEN RAISE EXCEPTION 'The linked % was not found in this company', v_type; END IF;
  END IF;
  IF v_type = 'customer' THEN v_cust := p_related_id; END IF;
  INSERT INTO crm_tasks(tenant_id, customer_id, assigned_to, created_by, task_type, priority, title, description, due_at, status,
                        visibility, related_type, related_id, module, board_column, start_at)
  VALUES (p_tenant_id, v_cust, p_assignees[1], auth.uid(), coalesce(p_task_type,'todo'), coalesce(p_priority,'normal'), p_title, p_description, p_due_at,
          'open', coalesce(p_visibility,'team'), v_type, p_related_id, p_module, coalesce(p_board_column, 'todo'), p_start_at)
  RETURNING id INTO v;
  FOREACH u IN ARRAY coalesce(p_assignees, '{}'::uuid[]) LOOP
    IF NOT EXISTS (SELECT 1 FROM tenant_memberships m WHERE m.tenant_id = p_tenant_id AND m.user_id = u AND coalesce(m.active, true)) THEN
      RAISE EXCEPTION 'Assignee % is not a member of this company', u;
    END IF;
    INSERT INTO crm_task_assignees(task_id, user_id, tenant_id) VALUES (v, u, p_tenant_id) ON CONFLICT DO NOTHING;
  END LOOP;
  RETURN v;
END $_$;

-- @seq 506
CREATE FUNCTION public.platform_integrity_report(p_deep boolean DEFAULT false) RETURNS TABLE(category text, table_name text, column_name text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; n bigint;
BEGIN
  IF NOT (platform_is_admin() OR coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
          OR current_user IN ('postgres','supabase_admin')) THEN
    RAISE EXCEPTION 'Platform admins only';
  END IF;

  -- FKs that exist but have rows pointing at nothing, or could not be added
  RETURN QUERY SELECT 'fk_' || l.status, l.child_table, l.child_column,
                      concat_ws('; ', '-> ' || l.parent_table, CASE WHEN l.orphan_rows IS NOT NULL THEN l.orphan_rows || ' orphan rows' END, l.detail)
                 FROM platform_fk_log l WHERE l.status IN ('not_valid_orphans','type_mismatch','no_unique_target','error');

  -- *_id columns with no FK that are not explained
  RETURN QUERY
  SELECT 'unconstrained_id', c.relname::text, a.attname::text,
         CASE WHEN format_type(a.atttypid, a.atttypmod) <> 'uuid' THEN 'non-uuid id (' || format_type(a.atttypid, a.atttypmod) || ')'
              ELSE 'uuid with no foreign key' END
    FROM pg_class c JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
    LEFT JOIN platform_table_registry g ON g.table_name = c.relname
   WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p') AND NOT c.relispartition
     AND a.attname LIKE '%\_id' AND a.attname <> 'id'
     AND coalesce(g.lifecycle, 'active') IN ('active')
     AND a.attname !~ '^(stripe|teller|resend|svix|shopify|etsy|amazon|ebay|tiktok|facebook|meta|google|whatnot|paypal|square|plaid|irs|provider|external|gateway|vercel|openai|printful|printify)_'
     AND a.attname NOT IN ('source_id','related_id','object_id','request_id','session_id','correlation_id','idempotency_key_id','trace_id')
     AND NOT EXISTS (SELECT 1 FROM pg_constraint f WHERE f.conrelid = c.oid AND f.contype = 'f' AND a.attnum = ANY (f.conkey))
     AND NOT EXISTS (SELECT 1 FROM platform_fk_exemptions e WHERE e.table_name = c.relname AND e.column_name = a.attname)
     AND NOT EXISTS (SELECT 1 FROM platform_polymorphic_columns p WHERE p.table_name = c.relname AND p.id_column = a.attname)
     AND NOT EXISTS (SELECT 1 FROM platform_fk_log l WHERE l.child_table = c.relname AND l.child_column = a.attname);

  -- tables with no FK in or out (dangling), excluding logs, reference and integration tables
  RETURN QUERY
  SELECT 'isolated_table', c.relname::text, NULL::text, 'no foreign keys in or out; lifecycle ' || coalesce(g.lifecycle, '?')
    FROM pg_class c LEFT JOIN platform_table_registry g ON g.table_name = c.relname
   WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p') AND NOT c.relispartition
     AND coalesce(g.lifecycle, 'active') IN ('active','legacy')
     AND NOT EXISTS (SELECT 1 FROM pg_constraint f WHERE f.contype = 'f' AND (f.conrelid = c.oid OR f.confrelid = c.oid));

  -- legacy tables still holding rows, and active tables still depending on them
  FOR r IN SELECT g.table_name t, g.canonical_table ct FROM platform_table_registry g
            WHERE g.lifecycle = 'legacy' AND to_regclass('public.' || quote_ident(g.table_name)) IS NOT NULL LOOP
    EXECUTE format('SELECT count(*) FROM (SELECT 1 FROM public.%I LIMIT 100001) x', r.t) INTO n;
    IF n > 0 THEN
      category := 'legacy_with_data'; table_name := r.t; column_name := NULL;
      detail := n || CASE WHEN n > 100000 THEN '+' ELSE '' END || ' rows; migrate to ' || coalesce(r.ct, '?') || ' before archiving';
      RETURN NEXT;
    END IF;
  END LOOP;
  RETURN QUERY
  SELECT 'active_depends_on_legacy', f.conrelid::regclass::text, a.attname::text, '-> ' || f.confrelid::regclass::text || ' (legacy)'
    FROM pg_constraint f
    JOIN pg_attribute a ON a.attrelid = f.conrelid AND a.attnum = ANY (f.conkey)
    JOIN platform_table_registry p ON p.table_name = f.confrelid::regclass::text AND p.lifecycle = 'legacy'
    LEFT JOIN platform_table_registry ch ON ch.table_name = f.conrelid::regclass::text
   WHERE f.contype = 'f' AND coalesce(ch.lifecycle, 'active') NOT IN ('legacy','archived')
     AND f.conrelid::regclass::text NOT IN ('platform_customer_identity_links','platform_vendor_identity_links');

  IF p_deep THEN
    -- rows that reference a parent in a different tenant (single-column FKs between tenant tables)
    FOR r IN
      SELECT f.conrelid::regclass::text ct, a.attname::text col, f.confrelid::regclass::text pt, pa.attname::text pcol
        FROM pg_constraint f
        JOIN pg_attribute a ON a.attrelid = f.conrelid AND a.attnum = f.conkey[1]
        JOIN pg_attribute pa ON pa.attrelid = f.confrelid AND pa.attnum = f.confkey[1]
       WHERE f.contype = 'f' AND array_length(f.conkey, 1) = 1 AND a.attname <> 'tenant_id'
         AND f.connamespace = 'public'::regnamespace AND f.confrelid <> f.conrelid
         AND EXISTS (SELECT 1 FROM pg_attribute x WHERE x.attrelid = f.conrelid AND x.attname = 'tenant_id' AND NOT x.attisdropped)
         AND EXISTS (SELECT 1 FROM pg_attribute x WHERE x.attrelid = f.confrelid AND x.attname = 'tenant_id' AND NOT x.attisdropped)
    LOOP
      EXECUTE format('SELECT count(*) FROM %s c JOIN %s p ON p.%I = c.%I WHERE c.tenant_id IS DISTINCT FROM p.tenant_id AND p.tenant_id IS NOT NULL',
                     r.ct, r.pt, r.pcol, r.col) INTO n;
      IF n > 0 THEN
        category := 'cross_tenant_reference'; table_name := r.ct; column_name := r.col;
        detail := n || ' rows point at a ' || r.pt || ' row in another tenant'; RETURN NEXT;
      END IF;
    END LOOP;
  END IF;
END $$;

-- @seq 507
CREATE FUNCTION public.platform_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM platform_admins
        WHERE user_id = auth.uid()
          AND (expires_at IS NULL OR expires_at > now())
    );
$$;

-- @seq 508
CREATE FUNCTION public.platform_is_tenant_admin(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT public.platform_is_admin() OR EXISTS (
    SELECT 1 FROM public.tenant_memberships tm
     WHERE tm.tenant_id = p_tenant_id AND tm.user_id = auth.uid()
       AND tm.active AND tm.status = 'active'
       AND lower(tm.role) IN ('owner','admin','administrator'));
$$;

-- @seq 509
CREATE FUNCTION public.platform_is_tenant_member(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT platform_is_admin() OR EXISTS (
        SELECT 1 FROM tenant_memberships AS tm
        WHERE tm.tenant_id = p_tenant_id
          AND tm.user_id = auth.uid()
          AND tm.active = true
          AND tm.status = 'active'
    );
$$;

-- @seq 510
CREATE FUNCTION public.platform_link_catalog(p_tenant_id uuid) RETURNS TABLE(step text, rows_linked bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE n bigint;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  UPDATE erp_products e SET catalog_product_id = p.id, updated_at = now()
    FROM products p
   WHERE e.tenant_id = p_tenant_id AND p.tenant_id = p_tenant_id AND e.catalog_product_id IS NULL
     AND (p.id = e.id OR (e.source_product_id IS NOT NULL AND (e.source_product_id = p.id::text OR e.source_product_id = p.source_product_id)))
     AND NOT EXISTS (SELECT 1 FROM erp_products x WHERE x.tenant_id = p_tenant_id AND x.catalog_product_id = p.id);
  GET DIAGNOSTICS n = ROW_COUNT; step := 'erp_products -> products'; rows_linked := n; RETURN NEXT;

  UPDATE erp_product_skus s SET catalog_variant_id = v.id, updated_at = now()
    FROM product_variants v
   WHERE s.tenant_id = p_tenant_id AND v.tenant_id = p_tenant_id AND s.catalog_variant_id IS NULL
     AND (v.id = s.id OR v.id = s.variant_id OR (s.sku IS NOT NULL AND lower(v.sku) = lower(s.sku)));
  GET DIAGNOSTICS n = ROW_COUNT; step := 'erp_product_skus -> product_variants'; rows_linked := n; RETURN NEXT;

  UPDATE erp_product_variants ev SET catalog_variant_id = s.catalog_variant_id, updated_at = now()
    FROM erp_product_skus s
   WHERE ev.tenant_id = p_tenant_id AND s.tenant_id = p_tenant_id AND s.variant_id = ev.id
     AND ev.catalog_variant_id IS NULL AND s.catalog_variant_id IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT; step := 'erp_product_variants -> product_variants'; rows_linked := n; RETURN NEXT;

  -- accounting items learn the storefront variant, so order lines find their COGS item
  UPDATE acct_items i SET product_variant_id = s.catalog_variant_id
    FROM erp_product_skus s
   WHERE i.tenant_id = p_tenant_id AND s.id = i.sku_id AND i.product_variant_id IS NULL AND s.catalog_variant_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM acct_items x WHERE x.tenant_id = p_tenant_id AND x.product_variant_id = s.catalog_variant_id);
  GET DIAGNOSTICS n = ROW_COUNT; step := 'acct_items <- product_variants'; rows_linked := n; RETURN NEXT;
END $$;

-- @seq 511
CREATE FUNCTION public.platform_link_legacy_orders(p_tenant_id uuid) RETURNS TABLE(legacy_table text, rows_linked bigint, rows_unlinked bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE t text; n bigint; m bigint;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  FOREACH t IN ARRAY ARRAY['orders','commerce_orders','sales_orders','ecommerce_orders'] LOOP
    EXECUTE format($q$
      UPDATE public.%1$I l SET erp_order_id = e.id
        FROM erp_orders e
       WHERE l.tenant_id = $1 AND e.tenant_id = $1 AND l.erp_order_id IS NULL
         AND (e.source_order_id = l.id::text OR e.metadata->>'legacy_order_id' = l.id::text
              OR e.metadata->>'%1$s_id' = l.id::text)$q$, t) USING p_tenant_id;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXECUTE format('SELECT count(*) FROM public.%I WHERE tenant_id = $1 AND erp_order_id IS NULL', t) INTO m USING p_tenant_id;
    legacy_table := t; rows_linked := n; rows_unlinked := m; RETURN NEXT;
  END LOOP;
END $_$;

-- @seq 512
CREATE FUNCTION public.platform_mark_chat_read(p_thread_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE platform_chat_members SET last_read_at = now() WHERE thread_id = p_thread_id AND user_id = auth.uid();
$$;

-- @seq 513
CREATE FUNCTION public.platform_move_task(p_task_id uuid, p_status text DEFAULT NULL::text, p_board_column text DEFAULT NULL::text, p_sort_order numeric DEFAULT NULL::numeric, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT platform__can_see_task(p_task_id) THEN RAISE EXCEPTION 'Task not found' USING ERRCODE = '42501'; END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('open','in_progress','blocked','done','cancelled') THEN
    RAISE EXCEPTION 'Task status must be open, in_progress, blocked, done or cancelled';
  END IF;
  UPDATE crm_tasks SET status = coalesce(p_status, status), board_column = coalesce(p_board_column, p_status, board_column),
         sort_order = coalesce(p_sort_order, sort_order), due_at = coalesce(p_due_at, due_at), start_at = coalesce(p_start_at, start_at),
         completed_at = CASE WHEN p_status = 'done' THEN now() WHEN p_status IS NOT NULL THEN NULL ELSE completed_at END, updated_at = now()
   WHERE id = p_task_id;
END $$;

-- @seq 514
CREATE FUNCTION public.platform_my_inbox(p_tenant_id uuid) RETURNS TABLE(kind text, item_id uuid, title text, detail text, due_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT platform_is_tenant_member(p_tenant_id) THEN RAISE EXCEPTION 'Not a member of this company' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  SELECT 'task'::text, t.id, t.title, t.status, t.due_at, t.created_at FROM crm_tasks t
   WHERE t.tenant_id = p_tenant_id AND t.status NOT IN ('done','cancelled','completed')
     AND (t.assigned_to = auth.uid() OR EXISTS (SELECT 1 FROM crm_task_assignees a WHERE a.task_id = t.id AND a.user_id = auth.uid()))
  UNION ALL
  SELECT 'chat', th.id, coalesce(th.title, 'Conversation'),
         (SELECT count(*)::text FROM platform_chat_messages msg WHERE msg.thread_id = th.id AND msg.deleted_at IS NULL
             AND msg.author_id IS DISTINCT FROM auth.uid() AND msg.created_at > coalesce(m.last_read_at, '-infinity')) || ' unread',
         NULL::timestamptz, th.last_message_at
    FROM platform_chat_threads th JOIN platform_chat_members m ON m.thread_id = th.id AND m.user_id = auth.uid()
   WHERE th.tenant_id = p_tenant_id AND NOT m.muted
     AND EXISTS (SELECT 1 FROM platform_chat_messages msg WHERE msg.thread_id = th.id AND msg.deleted_at IS NULL
                   AND msg.author_id IS DISTINCT FROM auth.uid() AND msg.created_at > coalesce(m.last_read_at, '-infinity'))
  UNION ALL
  SELECT 'announcement', a.id, a.title, left(a.body, 140), a.expires_at, a.published_at FROM platform_announcements a
   WHERE a.tenant_id = p_tenant_id AND a.published_at <= now() AND (a.expires_at IS NULL OR a.expires_at > now())
     AND (a.audience = 'all' OR platform_is_tenant_admin(p_tenant_id))
     AND NOT EXISTS (SELECT 1 FROM platform_announcement_reads r WHERE r.announcement_id = a.id AND r.user_id = auth.uid())
  UNION ALL
  SELECT 'mention', c.task_id, 'Mentioned on a task', left(c.body, 140), NULL, c.created_at FROM crm_task_comments c
   WHERE c.tenant_id = p_tenant_id AND auth.uid() = ANY (c.mentions) AND c.created_at > now() - interval '30 days'
  ORDER BY 6 DESC NULLS LAST;
END $$;

-- @seq 518
CREATE FUNCTION public.platform_polymorphic_orphans(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(table_name text, id_column text, type_value text, target_table text, orphan_rows bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE r record; v record; v_target text; n bigint; v_has_tenant boolean;
BEGIN
  IF p_tenant_id IS NULL THEN
    IF NOT (platform_is_admin() OR coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
            OR current_user IN ('postgres','supabase_admin')) THEN
      RAISE EXCEPTION 'All-tenant check is for platform admins; pass a tenant id';
    END IF;
  ELSE
    PERFORM acct_assert_access(p_tenant_id);
  END IF;
  FOR r IN SELECT p.* FROM platform_polymorphic_columns p WHERE to_regclass('public.' || quote_ident(p.table_name)) IS NOT NULL LOOP
    v_has_tenant := EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = r.table_name AND c.column_name = 'tenant_id');
    CONTINUE WHEN p_tenant_id IS NOT NULL AND NOT v_has_tenant;
    FOR v IN EXECUTE format('SELECT DISTINCT %I::text tv FROM public.%I WHERE %I IS NOT NULL AND %I IS NOT NULL %s',
                            r.type_column, r.table_name, r.type_column, r.id_column,
                            CASE WHEN p_tenant_id IS NOT NULL THEN 'AND tenant_id = ' || quote_literal(p_tenant_id) ELSE '' END) LOOP
      v_target := coalesce((SELECT m.target_table FROM platform_polymorphic_type_map m WHERE m.type_value = lower(v.tv)),
                           CASE WHEN to_regclass('public.' || quote_ident(lower(v.tv))) IS NOT NULL THEN lower(v.tv) END);
      CONTINUE WHEN v_target IS NULL;
      EXECUTE format('SELECT count(*) FROM public.%I c WHERE c.%I::text = $1 AND c.%I IS NOT NULL %s
                        AND NOT EXISTS (SELECT 1 FROM public.%I t WHERE t.id::text = c.%I::text)',
                     r.table_name, r.type_column, r.id_column,
                     CASE WHEN p_tenant_id IS NOT NULL THEN 'AND c.tenant_id = ' || quote_literal(p_tenant_id) ELSE '' END,
                     v_target, r.id_column) INTO n USING v.tv;
      IF n > 0 THEN
        table_name := r.table_name; id_column := r.id_column; type_value := v.tv; target_table := v_target; orphan_rows := n; RETURN NEXT;
      END IF;
    END LOOP;
  END LOOP;
END $_$;

-- @seq 519
CREATE FUNCTION public.platform_post_message(p_thread_id uuid, p_body text, p_attachments jsonb DEFAULT '[]'::jsonb, p_mentions uuid[] DEFAULT '{}'::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; v_t uuid;
BEGIN
  IF NOT platform__is_chat_member(p_thread_id) THEN RAISE EXCEPTION 'Not in this conversation' USING ERRCODE = '42501'; END IF;
  SELECT tenant_id INTO v_t FROM platform_chat_threads WHERE id = p_thread_id;
  INSERT INTO platform_chat_messages(tenant_id, thread_id, author_id, body, attachments, mentions)
  VALUES (v_t, p_thread_id, auth.uid(), p_body, coalesce(p_attachments,'[]'::jsonb), coalesce(p_mentions,'{}')) RETURNING id INTO v;
  UPDATE platform_chat_threads SET last_message_at = now() WHERE id = p_thread_id;
  UPDATE platform_chat_members SET last_read_at = now() WHERE thread_id = p_thread_id AND user_id = auth.uid();
  RETURN v;
END $$;

-- @seq 520
CREATE FUNCTION public.platform_revalidate_fks() RETURNS TABLE(child_table text, child_column text, status text, orphan_rows bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; v_orphans bigint;
BEGIN
  IF NOT (platform_is_admin() OR coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
          OR current_user IN ('postgres','supabase_admin')) THEN
    RAISE EXCEPTION 'Platform admins only';
  END IF;
  FOR r IN SELECT l.* FROM platform_fk_log l WHERE l.status = 'not_valid_orphans' LOOP
    BEGIN
      EXECUTE format('ALTER TABLE public.%I VALIDATE CONSTRAINT %I', r.child_table, r.constraint_name);
      UPDATE platform_fk_log SET status = 'validated', orphan_rows = 0, logged_at = now()
       WHERE platform_fk_log.child_table = r.child_table AND platform_fk_log.child_column = r.child_column;
      child_table := r.child_table; child_column := r.child_column; status := 'validated'; orphan_rows := 0; RETURN NEXT;
    EXCEPTION WHEN foreign_key_violation THEN
      EXECUTE format('SELECT count(*) FROM public.%I c WHERE c.%I IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.%I p WHERE p.id = c.%I)',
                     r.child_table, r.child_column, r.parent_table, r.child_column) INTO v_orphans;
      UPDATE platform_fk_log SET orphan_rows = v_orphans, logged_at = now()
       WHERE platform_fk_log.child_table = r.child_table AND platform_fk_log.child_column = r.child_column;
      child_table := r.child_table; child_column := r.child_column; status := 'not_valid_orphans'; orphan_rows := v_orphans; RETURN NEXT;
    END;
  END LOOP;
END $$;

-- @seq 521
CREATE FUNCTION public.platform_security_audit() RETURNS TABLE(table_name text, problem text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH t AS (
    SELECT c.relname::text AS t, c.relrowsecurity AS rls, c.relispartition AS part
      FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p'))
  SELECT t.t, 'RLS disabled' FROM t WHERE NOT t.rls
  UNION ALL
  SELECT t.t, 'RLS on but no policy and not service-only'
    FROM t LEFT JOIN platform_table_registry g ON g.table_name = t.t
   WHERE t.rls AND NOT t.part AND coalesce(g.access_mode,'') <> 'service_only'
     AND NOT EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=t.t AND p.policyname <> 'app_platform_admin')
     AND coalesce(g.access_mode,'') <> 'admin_only'
  UNION ALL
  SELECT p.tablename::text, 'policy allows all rows when tenant setting is unset: ' || p.policyname
    FROM pg_policies p WHERE p.schemaname='public'
     AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~* 'current_setting\(.app\.current_tenant_id.*IS NULL'
  UNION ALL
  SELECT p.tablename::text, 'USING (true) on a non-reference table: ' || p.policyname
    FROM pg_policies p LEFT JOIN platform_table_registry g ON g.table_name = p.tablename
   WHERE p.schemaname='public' AND (p.qual = 'true' OR p.with_check = 'true')
     AND coalesce(g.access_mode,'') NOT IN ('global_read','public_read')
     AND NOT (p.roles = ARRAY['service_role']::name[])
  UNION ALL
  SELECT t.t, 'not in registry' FROM t LEFT JOIN platform_table_registry g ON g.table_name = t.t
   WHERE g.table_name IS NULL AND NOT t.part
  UNION ALL
  SELECT g.table_name, 'service-only table still granted to a client role'
    FROM platform_table_registry g
   WHERE g.access_mode = 'service_only'
     AND (has_table_privilege('authenticated', 'public.' || quote_ident(g.table_name), 'SELECT')
       OR has_table_privilege('anon', 'public.' || quote_ident(g.table_name), 'SELECT'));
$$;

-- @seq 522
CREATE FUNCTION public.platform_start_chat(p_tenant_id uuid, p_member_ids uuid[], p_title text DEFAULT NULL::text, p_related_type text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; v_members uuid[]; v_key text; u uuid; v_kind text;
BEGIN
  IF NOT platform_is_tenant_member(p_tenant_id) THEN RAISE EXCEPTION 'Not a member of this company' USING ERRCODE = '42501'; END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_members FROM unnest(coalesce(p_member_ids,'{}'::uuid[]) || auth.uid()) x WHERE x IS NOT NULL;
  IF coalesce(array_length(v_members,1),0) < 2 AND p_related_id IS NULL THEN RAISE EXCEPTION 'Add at least one other person'; END IF;
  FOREACH u IN ARRAY v_members LOOP
    IF NOT EXISTS (SELECT 1 FROM tenant_memberships m WHERE m.tenant_id = p_tenant_id AND m.user_id = u AND coalesce(m.active, true)) THEN
      RAISE EXCEPTION 'User % is not a member of this company', u;
    END IF;
  END LOOP;
  v_kind := CASE WHEN p_related_id IS NOT NULL THEN 'record' WHEN array_length(v_members,1) = 2 AND p_title IS NULL THEN 'direct' ELSE 'group' END;
  IF v_kind = 'direct' THEN
    v_key := array_to_string(v_members, ':');
    SELECT id INTO v FROM platform_chat_threads WHERE tenant_id = p_tenant_id AND direct_key = v_key;
    IF v IS NOT NULL THEN RETURN v; END IF;
  END IF;
  INSERT INTO platform_chat_threads(tenant_id, kind, title, related_type, related_id, direct_key, created_by)
  VALUES (p_tenant_id, v_kind, p_title, p_related_type, p_related_id, v_key, auth.uid()) RETURNING id INTO v;
  INSERT INTO platform_chat_members(thread_id, user_id, tenant_id, role)
  SELECT v, x, p_tenant_id, CASE WHEN x = auth.uid() THEN 'owner' ELSE 'member' END FROM unnest(v_members) x;
  RETURN v;
END $$;

-- @seq 523
CREATE FUNCTION public.platform_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;

-- @seq 524
CREATE FUNCTION public.platform_user_tenant_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT tm.tenant_id
    FROM tenant_memberships AS tm
    WHERE tm.user_id = auth.uid()
      AND tm.active = true
      AND tm.status = 'active';
$$;

-- @seq 530
CREATE FUNCTION public.retention_prune(p_max_per_table integer DEFAULT 100000) RETURNS TABLE(table_name text, deleted_rows bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  batch integer;
  n integer;
  total bigint;
BEGIN
  total := 0;
  LOOP
    DELETE FROM public.analytics_events WHERE ctid IN (
      SELECT ctid FROM public.analytics_events
       WHERE created_at < now() - interval '540 days' LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.analytics_events', total;

  total := 0;
  LOOP
    DELETE FROM public.email_messages WHERE ctid IN (
      SELECT ctid FROM public.email_messages
       WHERE (status = 'SENT' AND "createdAt" < now() - interval '730 days')
          OR (status = 'FAILED' AND "createdAt" < now() - interval '90 days')
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.email_messages', total;

  total := 0;
  LOOP
    DELETE FROM public.commerce_outbox_events WHERE ctid IN (
      SELECT ctid FROM public.commerce_outbox_events
       WHERE (status = 'published' AND created_at < now() - interval '90 days')
          OR (status = 'dead_letter' AND created_at < now() - interval '180 days')
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.commerce_outbox_events', total;

  total := 0;
  LOOP
    DELETE FROM public.social_outbox_events WHERE ctid IN (
      SELECT ctid FROM public.social_outbox_events
       WHERE (status = 'done' AND created_at < now() - interval '90 days')
          OR (status = 'dead' AND created_at < now() - interval '180 days')
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.social_outbox_events', total;

  total := 0;
  LOOP
    DELETE FROM public.social_publish_attempts WHERE ctid IN (
      SELECT ctid FROM public.social_publish_attempts
       WHERE finished_at IS NOT NULL AND finished_at < now() - interval '365 days'
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.social_publish_attempts', total;

  total := 0;
  LOOP
    DELETE FROM public.crm_activity WHERE ctid IN (
      SELECT ctid FROM public.crm_activity
       WHERE occurred_at < now() - interval '365 days' LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.crm_activity', total;

  total := 0;
  LOOP
    DELETE FROM public.onboarding_events WHERE ctid IN (
      SELECT e.ctid FROM public.onboarding_events e
       JOIN public.onboarding_cases c ON c.id = e.case_id
      WHERE c.state IN ('REJECTED', 'OFFBOARDED') AND e.created_at < now() - interval '365 days'
      LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.onboarding_events', total;

  total := 0;
  LOOP
    DELETE FROM lms.notification_delivery_log WHERE ctid IN (
      SELECT ctid FROM lms.notification_delivery_log
       WHERE status IN ('sent', 'delivered', 'read', 'failed', 'bounced')
         AND created_at < now() - interval '180 days'
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'lms.notification_delivery_log', total;

  total := 0;
  LOOP
    DELETE FROM lms.notification_queue WHERE ctid IN (
      SELECT ctid FROM lms.notification_queue
       WHERE (status = 'sent' AND sent_at < now() - interval '90 days')
          OR (status IN ('failed', 'cancelled') AND updated_at < now() - interval '90 days')
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'lms.notification_queue', total;

  total := 0;
  LOOP
    DELETE FROM public.sync_jobs WHERE ctid IN (
      SELECT ctid FROM public.sync_jobs
       WHERE status IN ('succeeded', 'failed', 'dead') AND created_at < now() - interval '180 days'
       LIMIT 10000);
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    EXIT WHEN n = 0 OR total >= p_max_per_table;
  END LOOP;
  RETURN QUERY SELECT 'public.sync_jobs', total;
END;
$$;

